{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Perindopril, a structurally related ACE inhibitor prodrug, gave 30 ± 6% bioavailability of its active metabolite perindoprilat after oral dosing in cirrhotic patients, directly supporting F ≥ 20% for the query prodrug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Perindopril absolute bioavailability in healthy/fasted subjects is 66–95%, showing high oral absorption for an ACE inhibitor prodrug with ester and carboxylic acid features similar to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Captopril, a smaller ACE inhibitor, has an absolute oral bioavailability of approximately 60% in fasting healthy subjects, supporting high oral bioavailability for the ACE inhibitor class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Temocapril, another ACE inhibitor prodrug, yields about 65% absolute bioavailability of temocaprilat after oral administration, supporting high F for the query prodrug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Omapatrilat, a structurally related ACE/NEP inhibitor, has absolute oral bioavailability of 21.9–45% in humans, still above the 20% threshold and supportive of high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "SQ 29852, a phosphoryl-containing ACE inhibitor, is well absorbed orally with 66% bioavailability, directly relevant to the phosphinic acid/phosphoryl scaffold of the query.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence from ACE inhibitor prodrugs and related phosphoryl-containing drugs shows oral bioavailability at or above 20%, often 30–95%. The query is fosinopril, a prodrug of this class, so F ≥ 20% is strongly supported despite an unfavorable physicochemical prior.",
  "evidence_gaps": [
    "No direct fosinopril bioavailability measurement is included; prediction relies on close ACE inhibitor prodrug analogues.",
    "The physicochemical prior is mixed/unclear and suggests possible permeability limitations, but experimental analogues consistently show high F.",
    "Some analogue values, such as omapatrilat at 21.9%, are close to the threshold, adding minor quantitative uncertainty."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

